import { useMemo, useState } from 'react';
import { Link, useParams } from 'react-router-dom';

import usePageMeta from '../functions/usePageMeta.js';
import useToTop from '../functions/useToTop.js';
import productData from '../data/fireworks/productData.js';
import contactPageData from '../data/pages/contactPageData.js';
import NotFoundPage from './NotFoundPage.js';

const getCategory = (product) =>
  product.info.find((el) => el.name === 'Kategorija')?.value || '';

const ProductPage = () => {
  useToTop();
  const { id } = useParams();
  const [copied, setCopied] = useState(false);

  const product = useMemo(
    () => productData.find((item) => item.id === id && item.meta[0].display === 'yes'),
    [id]
  );

  const related = useMemo(() => {
    if (!product) return [];
    const category = getCategory(product);
    return productData
      .filter(
        (item) =>
          item.id !== product.id &&
          item.meta[0].display === 'yes' &&
          item.meta[0].sold !== 'yes' &&
          getCategory(item) === category
      )
      .slice(0, 4);
  }, [product]);

  usePageMeta({
    title: product ? `${product.id} - ${product.name}` : 'Produkts nav atrasts',
    description: product
      ? `${product.name} (${product.id}) — ${product.price[0].value} ${product.price[0].symbol}. Tropiks AZ pirotehnika Rīgā.`
      : 'Šis produkts netika atrasts Tropiks AZ katalogā.',
    path: product ? `/produkti/${product.id}` : undefined,
  });

  if (!product) {
    return <NotFoundPage />;
  }

  const { countryCode, phoneNumber, eMail } = contactPageData[0].contacts;
  const isSold = product.meta[0].sold === 'yes';
  const isNew = product.meta[0].new === 'yes';
  const mailSubject = encodeURIComponent(`Jautājums par ${product.id} - ${product.name}`);
  const mailBody = encodeURIComponent(
    `Sveiki!\n\nInteresējos par produktu ${product.id} - ${product.name}.\n\n`
  );
  const hasVideo = product.media[0].video !== '-';

  const copyLink = async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      setCopied(false);
    }
  };

  return (
    <main className="product-page">
      <section className="product-layout">
        <section className="product-media">
          <picture className="product-page-image">
            <source type="image/webp" srcSet={product.media[0].webp} />
            <img
              alt={`Bilde ar pirotehnisko izstrādājumu ${product.id} - ${product.name}`}
              src={product.media[0].img}
              width="480"
              height="480"
              loading="eager"
              decoding="async"
            />
          </picture>

          {hasVideo ? (
            <iframe
              className="video-frame"
              name="youtube-player"
              title="Youtube video, kurā var redzēt pirotehnisko izstrādājumu darbībā"
              src={`${product.media[0].video}${product.media[0].video.includes('?') ? '&' : '?'}rel=0`}
              allowFullScreen
              loading="lazy"
            />
          ) : (
            <p className="align-center product-video-missing">
              <i>
                *Pašlaik šim pirotehnikas izstrādājumam &quot;{product.id} - {product.name}&quot; nav
                pieejams demonstrācijas video
              </i>
            </p>
          )}
        </section>

        <section className="product-details">
          <div className="product-badges product-badges-inline">
            {isNew && <span className="product-badge product-badge-new">Jaunums</span>}
            {isSold && <span className="product-badge product-badge-sold">Izpārdots</span>}
          </div>

          <h1>
            {product.id}
            <br />
            <span>{product.name}</span>
          </h1>

          <p className="product-page-price">
            {product.price[0].value} {product.price[0].symbol}
          </p>

          <table>
            <thead>
              <tr>
                <th>ĪPAŠĪBA</th>
                <th>RAKSTUROJUMS</th>
              </tr>
            </thead>
            <tbody>
              {product.info.map((data) => (
                <tr key={data.name}>
                  <td>{data.name}</td>
                  <td>{data.value}</td>
                </tr>
              ))}
            </tbody>
          </table>

          <i className="product-vat-note">*Preču cena norādīta ar iekļautu PVN 21%</i>

          <section className="product-actions">
            <a className="button-link" href={`tel:${countryCode}${phoneNumber}`}>
              Zvanīt: {countryCode} {phoneNumber}
            </a>
            <a
              className="button-link button-link-secondary"
              href={`mailto:${eMail}?subject=${mailSubject}&body=${mailBody}`}
            >
              Rakstīt e-pastu par šo produktu
            </a>
            <button type="button" className="button-link button-link-ghost" onClick={copyLink}>
              {copied ? 'Saite nokopēta' : 'Kopēt produkta saiti'}
            </button>
            <Link to="/" className="text-link">
              ← Atpakaļ pie produktiem
            </Link>
          </section>
        </section>
      </section>

      {related.length > 0 && (
        <section className="related-products">
          <h2>Līdzīgi produkti</h2>
          <div className="related-products-grid">
            {related.map((item) => (
              <Link key={item.id} to={`/produkti/${item.id}`} className="related-product-card">
                <div className="related-product-image">
                  <picture>
                    <source type="image/webp" srcSet={item.media[0].webp} />
                    <img
                      src={item.media[0].img}
                      alt={item.name}
                      width="160"
                      height="160"
                      loading="lazy"
                      decoding="async"
                    />
                  </picture>
                </div>
                <span>
                  {item.id}
                  <br />
                  {item.name}
                </span>
                <strong>
                  {item.price[0].value} {item.price[0].symbol}
                </strong>
              </Link>
            ))}
          </div>
        </section>
      )}
    </main>
  );
};

export default ProductPage;
